                max_id = 0
                for p in root.findall(f".//{qn('p')}"):
                    try:
                        max_id = max(max_id, int(p.get("id")))
                    except Exception:
                        pass

                insert_after = template
                for idx in range(len(followup_paras), len(desired_lines)):
                    max_id += 1
                    new_p = deepcopy(template)
