                        if t is t0:
                            continue
                        t.text = ""
                    drop_empty_runs(new_p)
                    prune_layout_cache(new_p)

                    # Insert after the last follow-up paragraph.
                    pos = parent.index(insert_after)
                    parent.insert(pos + 1, new_p)
                    insert_after = new_p

        # --- Remove layout-cache elements in changed paragraphs only ---
        for p in changed_paras:
            prune_layout_cache(p)

        write_xml(tree, section_path)


